import * as M from './model.mjs';
import * as D from './data.mjs';
const context={identityId:'preview-guest',campaignId:'night-shift-demo'};
const root=document.getElementById('app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?new Intl.NumberFormat('ru-RU').format(n)+' eb':'—';
const STATS=D.STATS||M.STATS, LABELS=D.STAT_LABELS||M.STAT_LABELS, ROLES=D.CREATION_ROLES||M.CREATION_ROLES, SKILLS=D.CORE_SKILLS||M.CORE_SKILLS, BY_ID=D.SKILL_BY_ID||M.SKILL_BY_ID, GEAR=D.GEAR_OPTIONS||M.GEAR_OPTIONS;
const STEP_IDS=['identity','stats','career','pickup','lifepath','gear'];
const STEP_NAMES=['Образ','STAT','Профессия','Навыки','История','Снаряжение'];
let storageOK=true, restored=false, modal='', filter='', itemCategory='all', depth=0, toast='';
let state;try{const r=M.restoreSession(localStorage.getItem(M.storageKey(context)),context);state=r.state;restored=r.recovered;}catch{state=M.newSession(context);storageOK=false;}
function persist(){try{localStorage.setItem(M.storageKey(context),M.serializeSession(state));storageOK=true;}catch{storageOK=false;}const e=document.getElementById('save-label');if(e)e.textContent=saveLabel();const hint=document.getElementById('guide-context');if(hint)hint.textContent=guideLine();}
function saveLabel(){return storageOK?'Черновик сохранён в этом браузере':'Не удалось сохранить. Не закрывай вкладку.';}
const role=()=>ROLES.find(r=>r.id===state.draft.roleId);
const careerIds=()=>M.careerSkillIds(state.draft);
const statsTotal=()=>STATS.reduce((n,k)=>n+Number(state.draft.stats[k]||0),0);
const careerTotal=()=>careerIds().reduce((n,k)=>n+Number(state.draft.careerRanks[k]||0),0);
const pickupTotal=()=>state.draft.pickup.reduce((n,s)=>n+Number(s.rank||0),0);
const skillName=id=>BY_ID[id]?.name||id;
function act(action,renderNow=true){const before=state.screen+':'+state.step;state=M.reduceSession(state,action);persist();if(renderNow){if(before!==state.screen+':'+state.step){history.pushState({onboarding:true,screen:state.screen,step:state.step},'');depth++;window.scrollTo({top:0,behavior:'instant'});}render();}}
function patch(p,rerender=true){act({type:'PATCH_DRAFT',patch:p},rerender);}
function openModal(kind){if(!modal){history.pushState({onboarding:true,screen:state.screen,step:state.step,modal:kind},'');depth++;}else history.replaceState({...history.state,modal:kind},'');modal=kind;render();}
function closeModal(){modal='';render();if(history.state?.modal)history.back();}
function modalAction(action){modal='';history.replaceState({onboarding:true,screen:state.screen,step:state.step},'');act(action);}
function back(){if(modal){closeModal();return;}state=M.reduceSession(state,{type:'BACK'});history.replaceState({onboarding:true,screen:state.screen,step:state.step},'');persist();render();window.scrollTo({top:0,behavior:'instant'});}
function btn(text,action,cls='',attrs=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function field(label,name,value,extra=''){return `<label class="field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;}
function note(text){return `<p class="note">${text}</p>`;}
function select(label,name,value,items){return `<label class="field">${label}<select name="${name}">${items.map(x=>`<option value="${esc(x.value)}" ${x.value===value?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label>`;}
function errors(){return state.errors?.length?`<div class="errors" role="alert" tabindex="-1"><ul>${state.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:'';}
function footer(next,label='Продолжить',showBack=true){return `<footer class="sticky-actions"><div class="action-inner"><span id="save-label" class="save" role="status">${esc(saveLabel())}</span>${showBack?btn('← Назад','back','quiet'):''}${next?btn(label,next,'primary'):''}</div></footer>`;}
function header(){return `<header class="topbar"><a class="brand" href="../" aria-label="Вернуться в тестовый стенд">NC <b>CREW</b> / 2020</a><div class="top-actions"><span class="badge">ПРЕВЬЮ ВХОДА</span>${btn('⋯','about','icon quiet','aria-label="Помощь и настройки превью" title="Помощь"')}</div></header>`;}
function rail(){if(state.screen==='paths')return `<aside class="rail"><div class="campaign"><p class="eyebrow">NC-2020 / НАЧАЛО</p><h2>Твой путь</h2><p>Один стол. Две стороны экрана.</p></div></aside>`;if(state.flow==='host')return `<aside class="rail"><div class="campaign"><p class="eyebrow">ВЕДУЩИЙ / ЛОКАЛЬНОЕ ДЕМО</p><h2>${esc(state.host.draft.name||'Новая кампания')}</h2><p>Черновик ведущего</p></div><ol class="path">${['Настройка','Проверка','Приглашение','Лобби'].map((name,i)=>`<li class="${['hostSetup','hostReview','hostInvite','hostLobby'].indexOf(state.screen)===i?'active':''}"><span>0${i+1}</span>${name}</li>`).join('')}</ol></aside>`;const stages=['Приглашение','Твой персонаж','Сбор команды','Первый ход'];const current=state.screen==='invitation'?0:['choose','create','review'].includes(state.screen)?1:state.screen==='lobby'?2:3;return `<aside class="rail"><div class="campaign"><p class="eyebrow">ПРИГЛАШЕНИЕ / NC-2020</p><h2>Ночная смена</h2><p>Учебная кампания · Найт-Сити</p><p>Ведущий: демо-ГМ</p></div><ol class="path">${stages.map((s,i)=>`<li class="${i===current?'active':''}"><span>${i<current?'✓':'0'+(i+1)}</span>${s}</li>`).join('')}</ol><p class="note">Изолированный макет.<br>Связь и другие участники симулируются. Настоящая кампания не меняется.</p></aside>`;}
function invitation(){return `<p class="eyebrow">ВХОДЯЩЕЕ ПРИГЛАШЕНИЕ</p><h1>Тебя ждут<br>в Найт-Сити.</h1><p class="lead">Выбери персонажа, проверь лист и займи место за столом. Всё по пути, без поиска по меню.</p><section class="card"><div class="row"><div><span class="kicker">СЕССИЯ / ДЕМО</span><h2>Ночная смена</h2></div><span class="badge">CP2020</span></div><p class="note">Маленькая Италия · вечер<br>Ведущий ждёт заявки игроков.</p><div class="connection">Учебная проверка связи · сервер не используется</div></section><p class="note">Продолжишь как демо-гость. Пароль и регистрация для этого теста не нужны. Черновик остаётся только в этом браузере.</p>${restored?'<p class="statusline">Сохранённый прогресс восстановлен.</p>':''}<div class="toolbar">${btn('Я буду ведущим','select-host','quiet')}</div>${footer('accept','Выбрать персонажа',false)}`;}
function choose(){const saved=state.savedHeroes||state.saved||[];const list=Array.isArray(saved)?saved:Object.values(saved);return `<p class="eyebrow">ТВОЙ ПЕРСОНАЖ</p><h1>Кем выйдешь на улицы?</h1><p class="lead">Готовые примеры для быстрого теста. Или создай своего с любым набором навыков.</p><div class="cards">${btn('<span class="kicker">ПОЛНОЕ СОЗДАНИЕ</span><strong>Новый персонаж</strong><p>10 ролей, характеристики, навыки, история и снаряжение.</p><span class="arrow">↗</span>','new','card wide')}${state.drafts?.new?.name?btn(`<span class="kicker">ЧЕРНОВИК В ЭТОМ БРАУЗЕРЕ</span><strong>${esc(state.drafts.new.name)}</strong><p>Продолжить с сохранённого шага</p>`,'resume','card wide'):''}${Object.entries(state.drafts||{}).filter(([id,d])=>id.startsWith('archived-')&&d.name).map(([id,d])=>btn(`<span class="kicker">ПРЕДЫДУЩИЙ ЧЕРНОВИК</span><strong>${esc(d.name)}</strong><p>Продолжить создание</p>`,'hero','card wide',`data-hero="${esc(id)}"`)).join('')}${list.map(h=>btn(`<span class="kicker">СОХРАНЁННЫЙ ЛИСТ</span><strong>${esc(h.name||h.draft?.name)}</strong><p>${esc(h.role||h.draft?.roleId||'Локальный персонаж')}</p>`,'hero','card wide',`data-hero="${esc(h.id)}"`)).join('')}${btn('<span class="hero-monogram">R/</span><strong>Рэй</strong><span class="kicker">СОЛО</span><p>Наблюдательность, пистолеты и прикрытие. Проверить и изменить перед входом.</p>','hero','card','data-hero="ray"')}${btn('<span class="hero-monogram">V/</span><strong>Вега</strong><span class="kicker">ТЕХНИК</span><p>Электроника, ремонт и поддержка. Проверить и изменить перед входом.</p>','hero','card','data-hero="vega"')}</div>${note('Рэй и Вега здесь — отдельные демонстрационные листы. Это не твои сохранённые персонажи из APK.')}${footer(null,'',true)}`;}
