function rolePicker(){
  const selected=role(),view=state.rolePicker,preview=ROLES.find(r=>r.id===view.previewRoleId)||selected||ROLES[0],index=ROLES.indexOf(preview),chosen=preview.id===selected?.id;
  const parts=preview.summary.split(/(?<=\.) /),who=parts.shift(),ability=parts.join(' ');
  return `<section class="role-picker" id="role-picker" aria-label="Десять ролей Cyberpunk 2020"><p class="sr-only" id="role-announcement" role="status" aria-live="polite" aria-atomic="true"></p><div class="role-picker-head"><div><span class="eyebrow">ПРОФЕССИЯ / CP2020</span><p class="role-selection" id="role-selection" role="status">${selected?`В листе: <b>${esc(selected.label)}</b>`:'Роль ещё не выбрана'}</p></div><div class="role-mode" role="group" aria-label="Вид выбора роли">${btn('Карточки','role-mode','',`data-mode="cards" data-picker-focus="mode-cards" aria-pressed="${view.mode==='cards'}"`)}${btn('Список','role-mode','',`data-mode="list" data-picker-focus="mode-list" aria-pressed="${view.mode==='list'}"`)}</div></div>
    <div class="role-list" ${view.mode==='list'?'':'hidden'}>${select('Выбрать роль для листа','roleId',state.draft.roleId,[{value:'',label:'Выбрать роль'},...ROLES.map(r=>({value:r.id,label:r.label+' · '+r.english}))])}${selected?`<div class="role-list-summary"><p>${esc(selected.summary)}</p><span>${esc(selected.ability.name)} · ${esc(selected.ability.english)}</span></div>`:''}<details><summary>Сравнить все 10 ролей</summary><div>${ROLES.map(r=>`<p class="note"><b>${esc(r.label)}.</b> ${esc(r.summary)}</p>`).join('')}</div></details></div>
    ${view.mode==='cards'?`<div class="role-filmstrip" role="group" aria-label="Просмотр ролей, выбор отдельной кнопкой">${ROLES.map((r,i)=>btn(`<span class="role-chip-number">${String(i+1).padStart(2,'0')}</span>${esc(r.label)}${r.id===selected?.id?'<span class="role-chip-check" aria-label="выбрана">✓</span>':''}`,'role-preview','role-chip',`data-role="${r.id}" data-picker-focus="preview-${r.id}" aria-pressed="${r.id===preview.id}"`)).join('')}</div><div class="role-deck" data-role-deck tabindex="0" aria-label="Просмотр ролей. Стрелки влево и вправо листают карточки; выбор отдельной кнопкой." data-picker-focus="deck"><article class="role-card" aria-labelledby="role-title" data-role-card="${preview.id}"><div class="role-illustration" data-role-swipe>${roleArt(preview.id)}<span class="role-art-label">${esc(preview.english).toUpperCase()} / CORE</span></div><div class="role-copy"><div class="role-title-row"><div><h2 id="role-title">${esc(preview.label)}</h2><p class="role-english">${esc(preview.english)}</p></div><span class="role-position">${String(index+1).padStart(2,'0')}<small>/ 10</small></span></div><p class="role-who">${esc(who)}</p><dl class="role-facts"><div><dt>В команде</dt><dd>${esc(ROLE_TEAM[preview.id])}</dd></div><div><dt>${esc(preview.ability.name)}</dt><dd>${esc(ability)}</dd></div></dl></div></article><div class="role-deck-actions">${btn('←','role-prev','quiet',`aria-label="Предыдущая роль" data-picker-focus="prev"`)}${btn(chosen?'✓ Роль выбрана':'Выбрать: '+esc(preview.label),'role-choose',chosen?'role-chosen':'primary',`data-role="${preview.id}" data-picker-focus="choose" ${chosen?'disabled':''}`)}${btn('→','role-next','quiet',`aria-label="Следующая роль" data-picker-focus="next"`)}</div></div><p class="role-browse-note">Листай роли. В лист попадёт только выбранная.</p>`:''}</section>`;
}
function identity(){return `${field('Имя / уличный псевдоним','name',state.draft.name,'maxlength="80" autocomplete="off" placeholder="Как тебя знают на улице?"')}${rolePicker()}`;}
function updateRolePicker(action,focus){
  roleSwipe=null;
  const strip=document.querySelector('.role-filmstrip'),left=strip?.scrollLeft||0;
  const announcement=document.getElementById('role-announcement');
  act(action,false);document.getElementById('role-picker').outerHTML=rolePicker();
  if(announcement){document.getElementById('role-announcement').replaceWith(announcement);const preview=ROLES.find(r=>r.id===state.rolePicker.previewRoleId);announcement.textContent=action.type==='PATCH_DRAFT'?`Выбрана роль: ${preview.label}.`:`Просмотр: ${preview.label}, ${ROLES.indexOf(preview)+1} из 10. ${preview.summary}`;}
  if(!state.errors.length)document.querySelector('#content>.errors')?.remove();
  const newStrip=document.querySelector('.role-filmstrip');if(newStrip)newStrip.scrollLeft=left;
  if(focus){const target=document.querySelector(`[data-picker-focus="${focus}"]`);(target&&!target.disabled?target:document.querySelector('[data-role-deck]'))?.focus({preventScroll:true});}
  const active=newStrip?.querySelector('[aria-pressed="true"]');if(active&&newStrip){const a=active.getBoundingClientRect(),b=newStrip.getBoundingClientRect();if(a.left<b.left)newStrip.scrollLeft-=b.left-a.left;else if(a.right>b.right)newStrip.scrollLeft+=a.right-b.right;}
}
function browseRole(offset,focus){const index=ROLES.findIndex(r=>r.id===state.rolePicker.previewRoleId);updateRolePicker({type:'PREVIEW_ROLE',roleId:ROLES[(index+offset+ROLES.length)%ROLES.length].id},focus);}

function stats(){return `<p class="note">В этом тесте ведущий выделил 60 очков. Это настройка учебной кампании, а не универсальная сумма Core. Базовые значения: 2–10.</p><div class="readout ${statsTotal()!==state.draft.budget?'over':''}"><span>Распределено / бюджет</span><strong>${statsTotal()} / ${state.draft.budget}</strong></div><div class="toolbar">${btn('Равномерно','balance-stats')}${btn('Профиль для роли','role-stats')}</div><div class="stat-grid">${STATS.map(k=>`<div class="stat"><label for="stat-${k}"><b>${k}</b> · ${esc(LABELS[k])}</label><input id="stat-${k}" name="stat.${k}" type="number" inputmode="numeric" min="2" max="10" step="1" value="${state.draft.stats[k]}"></div>`).join('')}</div><details><summary>Бюджет по решению ведущего</summary><div>${field('Очки STAT','budget',state.draft.budget,'type="number" min="18" max="90" inputmode="numeric"')}${note('Меняет только учебный лист. Распредели весь выбранный бюджет.')}</div></details>`;}
function career(){const r=role();return `<p class="note">40 очков на специальную способность и девять карьерных навыков. Значения 0–10. Готовое распределение можно полностью изменить.</p>${r?.id==='solo'?select('Боевой навык Соло','soloCombat',state.draft.soloCombat,[{value:'brawling',label:'Драка'},...SKILLS.filter(s=>['aikido','boxing','judo','karate','wrestling','thai-boxing','capoeira','choi-li-fut','tae-kwon-do','animal-kung-fu'].includes(s.id)).map(s=>({value:s.id,label:s.name}))]):''}${r?.id==='techie'?`<details open><summary>Три технические специализации</summary><div>${[0,1,2].map(i=>select('Специализация '+(i+1),'tech.'+i,state.draft.techChoices[i],[{value:'',label:'Выбрать'},...SKILLS.filter(s=>s.stat==='TECH'&&!r.career.includes(s.id)).map(s=>({value:s.id,label:s.name}))])).join('')}</div></details>`:''}<div class="readout ${careerTotal()!==40?'over':''}"><span>Карьерные очки</span><strong>${careerTotal()} / 40</strong></div><div class="toolbar">${btn('Предложить распределение','suggest-career')}</div>${careerIds().map(id=>`<div class="skill-row"><label for="career-${id}">${esc(skillName(id))}<small>${id===r?.ability.id?'Специальная способность':BY_ID[id]?.stat||''}</small></label><input id="career-${id}" name="career.${id}" type="number" inputmode="numeric" min="0" max="10" value="${state.draft.careerRanks[id]||0}">${BY_ID[id]?.detailLabel?`<label class="field detail"><input name="detail.${id}" aria-label="${esc(BY_ID[id].detailLabel)}" placeholder="${esc(BY_ID[id].detailLabel)}" value="${esc(state.draft.careerDetails[id]||'')}" maxlength="60"></label>`:''}</div>`).join('')}`;}
function pickup(){const available=SKILLS.filter(s=>!careerIds().includes(s.id));const matches=available.filter(s=>(s.name+' '+s.english).toLowerCase().includes(filter.toLowerCase()));return `<p class="note">INT + REF = ${state.draft.stats.INT+state.draft.stats.REF} очков на другие навыки. Карьерные навыки сюда не входят. Родной язык получишь отдельно на +8.</p><div class="readout ${pickupTotal()!==state.draft.stats.INT+state.draft.stats.REF?'over':''}"><span>Дополнительные очки</span><strong>${pickupTotal()} / ${state.draft.stats.INT+state.draft.stats.REF}</strong></div><div class="toolbar">${btn('Предложить навыки','suggest-pickup')}</div>${state.draft.pickup.map((s,i)=>`<div class="card"><div class="skill-row"><label for="pickup-${i}">${esc(skillName(s.skillId))}<small>${BY_ID[s.skillId]?.stat||''}</small></label><input id="pickup-${i}" name="pickup.${i}.rank" type="number" inputmode="numeric" min="1" max="10" value="${s.rank}"></div>${BY_ID[s.skillId]?.detailLabel?field(BY_ID[s.skillId].detailLabel,`pickup.${i}.detail`,s.detail,'maxlength="60"'):''}${btn('Убрать','remove-pickup','quiet small',`data-index="${i}"`)}</div>`).join('')}<details open><summary>Добавить любой навык</summary><div><label class="field">Поиск<input id="skill-search" value="${esc(filter)}" placeholder="Например, вождение" autocomplete="off"></label><div class="choice-list" id="skill-results">${matches.map(s=>btn(`${esc(s.name)} <span class="note">${s.stat}</span>`,'add-pickup','',`data-skill="${s.id}"`)).join('')}</div></div></details>`;}
function lifepath(){const l=state.draft.lifepath;return `${field('Родной язык · +8 бесплатно','nativeLanguage',state.draft.nativeLanguage,'maxlength="60" placeholder="Например, русский"')}<div class="split">${field('Возраст','life.age',l.age,'type="number" min="16" max="100" inputmode="numeric"')}${field('Происхождение','life.origin',l.origin,'maxlength="120" placeholder="Город, культура, семья"')}</div>${field('Что для тебя важнее всего?','life.motivation',l.motivation,'maxlength="240" placeholder="Человек, свобода, влияние…"')}<label class="field">Коротко о прошлом<textarea name="history" maxlength="6000" placeholder="Что привело тебя в Найт-Сити?">${esc(state.draft.history)}</textarea></label><label class="check"><input name="historyLater" type="checkbox" ${state.draft.historyLater?'checked':''}>Дописать историю после теста</label><details><summary>Стиль, семья, связи и события</summary><div>${field('Одежда и внешность','life.style',l.style,'maxlength="240"')}${field('Семья','life.family',l.family,'maxlength="300"')}${field('Важный человек / связь','life.contact',l.contact,'maxlength="300"')}<label class="field">Ключевые события<textarea name="life.events" maxlength="1500">${esc(l.events)}</textarea></label>${note('Свободное описание Lifepath. Автоматическую таблицу случайных событий это превью не имитирует.')}</div></details>`;}
function cashView(){const c=state.draft.cash,q=M.cashQuote(state.draft);return `<section class="card"><h2>Стартовые деньги</h2><p class="note">Core 2020, стр. 25, 58–59. Оклад зависит от роли и ранга способности. Число месяцев = d6 ÷ 3, вниз, минимум 1: результаты 1–5 дают месяц, 6 — два.</p><div class="split">${field('Бросок d6 · месяцы','cashRoll',c.cashRoll??'','type="number" min="1" max="6" inputmode="numeric"')}${field('Бросок d6 · работа','employmentRoll',c.employmentRoll??'','type="number" min="1" max="6" inputmode="numeric"')}</div><div class="toolbar">${btn('Бросить два d6','roll-cash')}${btn('Рассчитать по введённым','quote-cash')}</div><p id="cash-stale" class="errors" ${c.stale?'':'hidden'}>Параметры изменены. Подтверди новый расчёт; прежние броски не перебрасываются.</p><div class="readout"><span>Стартовый капитал</span><strong id="cash-value">${money(q.amount??q.total??q.cash)}</strong></div><p class="note">${esc(q.message||q.reason||'Броски не меняются при возврате или перезагрузке.')} ${c.mode==='manual'?'Применена отдельно согласованная сумма демо-ГМ.':q.amount!==null?'Оклад '+money(q.salary)+' × '+q.months+' мес. · '+(q.unemployed?'Недавно потерял работу.':'Работа пока есть.'):c.mode==='core'&&c.salary===null?'Для ранга способности 0 нет табличного оклада. Выбери сумму по решению ГМ.':'Нажми расчёт или сделай броски.'}</p><details><summary>Сумма по отдельному решению ГМ</summary><div>${field('Согласованная сумма, eb','cashManual',c.manualAmount??'','type="number" min="0" inputmode="numeric"')}${btn('Применить как решение демо-ГМ','manual-cash','demo-action')}${note('Не заменяет правило Core по умолчанию. Для ранга способности 0 табличного оклада нет.')}</div></details></section>`;}
function gear(){const items=GEAR.filter(i=>itemCategory==='all'||i.category===itemCategory);const total=M.gearTotal(state.draft);return `${cashView()}<h2>Снаряжение</h2><p class="note">Покупки вычитаются из стартового капитала. Цены взяты из справочника приложения; установка и условия имплантов требуют отдельной проверки.</p><div class="readout"><span>Выбрано снаряжения</span><strong>${money(typeof total==='number'?total:total.total)}</strong></div>${state.draft.gear.length?`<div class="card">${state.draft.gear.map((g,i)=>`<div class="row"><p class="small">${esc(GEAR.find(x=>x.id===g.itemId)?.name||g.itemId)} ×${g.quantity}</p>${btn('Убрать','remove-gear','quiet small',`data-index="${i}"`)}</div>`).join('')}</div>`:''}<details open><summary>Каталог учебного набора</summary><div>${items.map(i=>`<div class="equipment"><div><h3>${esc(i.name)}</h3><p>${esc(i.label||i.name||'')}</p><span class="price">${money(i.price?.value)}</span></div>${btn('+','add-gear','icon',`data-item="${esc(i.id)}" aria-label="Добавить ${esc(i.name)}"`)}</div>`).join('')}</div></details><label class="check"><input name="gearSkipped" type="checkbox" ${state.draft.gearSkipped?'checked':''}>Покупки можно уточнить после создания</label>${note('В этом превью импланты остаются приобретёнными, но не установленными: эффект на Humanity и характеристики не применяется автоматически.')}`;}
function create(){const i=STEP_IDS.indexOf(state.step);const titles=['Сначала — твой образ.','На что ты способен?','Твоё ремесло.','Что ещё ты умеешь?','За каждым именем — история.','С чем идёшь на улицу?'];return `<div class="stepper" aria-label="Шаги создания">${STEP_IDS.map((s,j)=>btn(STEP_NAMES[j],'step',j===i?'current':j<i?'past':'',`data-step="${s}" aria-label="Шаг ${j+1}: ${STEP_NAMES[j]}"`)).join('')}</div><p class="step-count">СОЗДАНИЕ / ${i+1} ИЗ 6</p><h1>${titles[i]||'Твой персонаж'}</h1>${({identity,stats,career,pickup,lifepath,gear}[state.step]||identity)()}${errors()}${footer('next',i===5?'Проверить лист':'Продолжить')}`;}
function review(){const d=state.draft,q=M.cashQuote(d),total=M.gearTotal(d);return `<p class="eyebrow">ПРОВЕРКА ЛИСТА</p><h1>${esc(d.name||'Твой персонаж')}</h1><p class="lead">${esc(role()?.label||'Роль')} · ${esc(role()?.ability.name||'Способность')} +${d.careerRanks[role()?.ability.id]||0}</p><div class="summary-grid"><div class="card"><span class="eyebrow">STAT</span><strong>${statsTotal()} / ${d.budget}</strong><p class="note">${STATS.map(k=>k+' '+d.stats[k]).join(' · ')}</p>${btn('Изменить','step','quiet small','data-step="stats"')}</div><div class="card"><span class="eyebrow">НАВЫКИ</span><strong>40 + ${d.stats.INT+d.stats.REF}</strong><p class="note">Карьерные и дополнительные</p>${btn('Изменить','step','quiet small','data-step="career"')}</div><div class="card"><span class="eyebrow">В КОШЕЛЬКЕ</span><strong>${money((q.amount??q.total??q.cash??0)-(typeof total==='number'?total:total.total||0))}</strong><p class="note">После выбранных покупок</p>${btn('Изменить','step','quiet small','data-step="gear"')}</div><div class="card"><span class="eyebrow">ИСТОРИЯ</span><strong>${esc(d.nativeLanguage||'Язык не выбран')}</strong><p class="note">${esc(d.history||'История будет дополнена')}</p>${btn('Изменить','step','quiet small','data-step="lifepath"')}</div></div><details><summary>Полный список навыков и вещей</summary><div>${careerIds().map(id=>`<p class="small">${esc(skillName(id))}: ${d.careerRanks[id]||0}</p>`).join('')}${d.pickup.map(s=>`<p class="small">${esc(skillName(s.skillId))} ${esc(s.detail)}: ${s.rank}</p>`).join('')}${d.gear.map(g=>`<p class="small">${esc(GEAR.find(x=>x.id===g.itemId)?.name||g.itemId)} ×${g.quantity}</p>`).join('')}</div></details>${errors()}${note('Сохранится отдельный локальный лист. После этого заявка попадёт в учебное лобби, где принятие ведущим показано отдельным действием.')}${footer('save-and-join','Сохранить и войти в лобби')}`;}
function lobby(){const l=state.lobby||{};const accepted=l.application==='accepted',ready=l.ready;return `<p class="eyebrow">ЛОББИ / НОЧНАЯ СМЕНА</p><h1>${accepted?'Ты в команде.':'Заявка у ведущего.'}</h1><p class="lead">${accepted?'Проверь лист и отметь готовность. Сцена начнётся, когда ведущий добавит твоего персонажа.':'Лист сохранён. В настоящей игре ведущий принимает заявку; здесь это можно проверить сразу.'}</p><section class="card"><div class="person"><div class="avatar">${esc(state.draft.name.slice(0,1)||'Я')}</div><div class="grow"><b>${esc(state.draft.name)}</b><p>${esc(role()?.label)} · твой локальный лист</p></div><span class="pill ${!accepted?'wait':''}">${!accepted?'Заявка':ready?'Готов':'Принят'}</span></div><div class="person"><div class="avatar">GM</div><div class="grow"><b>Ведущий</b><p>Демонстрационный участник</p></div><span class="pill wait">Готовит сцену</span></div><div class="person"><div class="avatar">02</div><div class="grow"><b>Второй игрок</b><p>Демонстрационный участник</p></div><span class="pill wait">Выбирает лист</span></div></section>${!accepted?btn('Демо: ведущий принимает заявку','accept-hero','demo-action'):ready?`<p class="statusline">Твоя готовность отмечена локально.</p>${btn('Демо: ведущий подготовил сцену','prepare-scene','demo-action')}`:note('Следующий шаг — твоя готовность. Этот макет не показывает реальное присутствие других игроков.')}<div class="toolbar">${btn('Посмотреть / изменить лист','edit-hero','quiet')}</div>${errors()}${footer(accepted?'ready':null,ready?'Снять готовность':'Я готов')}`;}
function scene(){return `<p class="eyebrow">ПЕРВАЯ СЦЕНА / ДЕМО</p><h1>Твой персонаж добавлен.</h1><p class="lead">Ведущий объявил сцену. Дальше ты увидишь только своё доступное действие.</p><section class="card"><span class="kicker">УЧЕБНОЕ ДЕЙСТВИЕ</span><h2>Перейти к укрытию</h2><p class="note">Выбери клетку, проверь намерение и отправь его ведущему. Фишка переместится только после подтверждения.</p></section>${btn('Демо: наступил мой ход','start-turn','demo-action')}${footer(null)}`;}
function action(){const a=state.firstAction||{};const confirmed=a.status==='confirmed',pending=a.status==='pending'||a.status==='submitted',preview=a.status==='preview';const target=a.to||{};return `<p class="eyebrow">${confirmed?'ДЕЙСТВИЕ ПОДТВЕРЖДЕНО':'ТВОЙ ХОД / УЧЕБНАЯ СЦЕНА'}</p><h1>${confirmed?'Ты за укрытием.':pending?'Намерение у ведущего.':preview?'Вот твой маршрут.':'Куда идём?'}</h1><p class="lead">${confirmed?'Приглашение, персонаж и первый ход пройдены.':pending?'До подтверждения положение персонажа не меняется.':preview?'Отправь намерение. Ведущий решит, проходит ли действие.':'Нажми подсвеченную доступную клетку. Это отдельная схема проверки входа, без расчёта боя.'}</p><div class="map" aria-label="Учебная схема первого действия">${Array.from({length:20},(_,i)=>{const x=i%5,y=Math.floor(i/5),own=confirmed?x===target.x&&y===target.y:x===1&&y===2,blocked=y===0||x===4,selected=x===target.x&&y===target.y;return btn(own?'ТЫ':blocked?'':selected?'◎':'·','cell',`cell ${own?'actor':''} ${blocked?'blocked':''} ${selected?'target':''}`,`data-x="${x}" data-y="${y}" aria-label="${own?'Твой персонаж':blocked?'Стена':'Клетка '+(x+1)+', '+(y+1)}" ${blocked||own||pending||confirmed?'disabled':''}`);}).join('')}</div>${pending?btn('Демо: ГМ подтверждает перемещение','confirm-action','demo-action'):''}${confirmed?'<div class="success-icon">✓</div><p class="note">Этот результат сохранён только в превью. Можно вернуться к выбору персонажа и проверить другой путь.</p>':''}${errors()}${footer(confirmed?'again':pending?null:preview?'send-action':'preview-action',confirmed?'Другой персонаж':preview?'Отправить ГМу':'Проверить действие')}`;}
// The guide's voice lives here so dialogue can be tuned without touching rules.
function guideLine(){
  if(state.screen==='paths')return 'Сам станешь эджраннером или поведёшь команду? Выбери свою сторону экрана.';
  if(state.screen==='invitation')return 'Приглашение уже на деке. Нажми «Выбрать персонажа», чтобы зайти за игровой стол.';
  if(state.screen==='choose')return 'Нужен эджраннер. Создай своего или открой любой учебный лист, чтобы проверить его.';
  if(state.screen==='create')return {
    identity:'Начнём с имени и роли. Кем тебя узнают на улицах?',
    stats:'Разложи очки по характеристикам до указанного бюджета. Каждое число здесь на твоей стороне.',
    career:'Распредели 40 очков по карьерным навыкам. Это твоё ремесло, чумба.',
    pickup:'Распредели INT + REF по дополнительным навыкам. Уличные сюрпризы любят запасной план.',
    lifepath:'Укажи родной язык. Историю можно набросать сейчас или явно оставить на потом.',
    gear:M.cashQuote(state.draft).amount===null?'Начни со стартовых денег: введи два d6 и нажми расчёт. Без тайных перебросов, честно.)':'С деньгами разобрались. Выбери снаряжение или явно отложи покупки.'
  }[state.step];
  if(state.screen==='review')return 'Пробеги глазами лист. Всё твоё? Сохрани его и переходи в учебное лобби.';
  if(state.screen==='lobby')return state.lobby.application!=='accepted'?'Заявка ждёт. Здесь можешь сам показать, как демо-ГМ её принимает.':state.lobby.ready?'Команда почти собралась. Покажи, что демо-ГМ подготовил сцену.':'Ты принят. Отметь «Я готов», когда захочешь перейти к сцене.';
  if(state.screen==='scene')return 'Твой выход. Нажми «Демо: наступил мой ход» и попробуй первое действие.';
  if(state.screen==='action')return {idle:'Выбери доступную клетку. Проверим маршрут до того, как двинемся.',declared:'Клетка выбрана. Нажми «Проверить действие».',preview:'Маршрут виден. Отправь намерение демо-ГМу.',submitted:'Намерение на рассмотрении. Покажи подтверждение ГМа, чтобы фишка переместилась.',confirmed:'Вот и первый шаг. Добро пожаловать, эджраннер.)'}[state.firstAction.status];
  return {
    hostSetup:'Собираешь команду? Задай название, завязку и бюджет STAT. Начнём с твоего замысла.',
    hostReview:'Проверь замысел и бюджет. Готово? Собери учебное приглашение.',
    hostInvite:'Вот как приглашение будет выглядеть для команды. Открой учебное лобби.',
    hostLobby:state.host.playerSimulated?'Первый учебный эджраннер за столом. Черновик сохранён, можно вернуться к настройке.':'Стол готов. Добавь учебного игрока и посмотри, как меняется лобби.'
  }[state.screen]||'Я рядом, если понадобится подсказка.';
}
function guideView(){
  const g=state.guide;
  if(g.preference==='unanswered')return `<section class="guide-call" aria-label="Текстовый вызов Анри">${btn(`<span>АНРИ / ТЕКСТОВЫЙ ВЫЗОВ · СЦЕНКА</span><span aria-hidden="true">${g.collapsed?'+':'−'}</span>`,'guide-collapse','guide-heading',`aria-expanded="${!g.collapsed}" aria-controls="guide-call-content"`)}${g.collapsed?'':`<div id="guide-call-content"><p>О, новый сигнал. Привет, впервые тут?) Я Анри, нетраннер. Могу помочь освоиться.</p><div class="guide-answers">${btn('Да, помоги','guide-yes','primary')}${btn('Пропустить','guide-skip','quiet')}${btn('Уже знаком','guide-familiar','quiet')}</div></div>`}</section>`;
  if(g.preference!=='enabled')return '';
  return `<aside class="guide-panel" aria-label="Подсказка Анри">${btn(`<span>АНРИ / ${g.collapsed?'Подсказка':'На связи'}</span><span aria-hidden="true">${g.collapsed?'+':'−'}</span>`,'guide-collapse','guide-heading',`aria-expanded="${!g.collapsed}" aria-controls="guide-context"`)}${!g.collapsed?`<p id="guide-context">${esc(guideLine())}</p>`:''}</aside>`;
}
function paths(){return `<p class="eyebrow">НАЧАЛО / ВЫБОР ПУТИ</p><h1>Кем будешь за столом?</h1><p class="lead">Можно вернуться сюда через «Помощь». Оба черновика сохраняются отдельно.</p><div class="cards"><button type="button" data-action="select-player" class="card"><span class="kicker">ИГРОК</span><strong>Стать эджраннером</strong><p>Создать или выбрать героя и присоединиться к ведущему.</p><span class="arrow">↗</span></button><button type="button" data-action="select-host" class="card"><span class="kicker">ВЕДУЩИЙ / ГМ</span><strong>Собрать команду</strong><p>Создать свою кампанию и подготовить учебное приглашение.</p><span class="arrow">↗</span></button></div>${note('Это локальный макет: учётная запись и реальное подключение не нужны.')}${footer(null)}`;}
function hostSetup(){const d=state.host.draft;return `<p class="eyebrow">ВЕДУЩИЙ / НАСТРОЙКА</p><h1>С чего начнётся история?</h1><p class="lead">Задай основу своей учебной кампании.</p>${field('Название кампании','host.name',d.name,'maxlength="80" autocomplete="off"')}<label class="field">Завязка<textarea name="host.premise" maxlength="1200" placeholder="Одно-два предложения для команды">${esc(d.premise)}</textarea></label>${field('Бюджет STAT по решению ведущего','host.budget',d.budget??'','type="number" min="18" max="90" step="1" inputmode="numeric"')}${note('60 — редактируемый пример, не универсальное правило Core. Этот бюджет относится только к черновику ведущего.')}${errors()}${footer('review-host','Проверить кампанию')}`;}
function hostReview(){const d=state.host.draft;return `<p class="eyebrow">ВЕДУЩИЙ / ПРОВЕРКА</p><h1>${esc(d.name)}</h1><section class="card"><p class="host-premise">${esc(d.premise)}</p><div class="readout"><span>Бюджет STAT для игроков</span><strong>${d.budget}</strong></div></section>${note('Следующий экран покажет учебное приглашение. Оно никуда не отправляется; настоящая кампания не создаётся.')}${errors()}${footer('prepare-host-invite','Собрать учебное приглашение')}`;}
function hostInvite(){const d=state.host.draft;return `<p class="eyebrow">УЧЕБНОЕ ПРИГЛАШЕНИЕ</p><h1>Команда, сбор.</h1><section class="card"><span class="kicker">ОБРАЗЕЦ / ТОЛЬКО В ЭТОМ БРАУЗЕРЕ</span><h2>${esc(d.name)}</h2><p class="host-premise">${esc(d.premise)}</p><p>Бюджет STAT: ${d.budget} · ведущий: ты</p></section>${note('Это образец приглашения без действующей ссылки или кода. Участники не подключаются по сети.')}${footer('open-host-lobby','Открыть учебное лобби')}`;}
function hostLobby(){const d=state.host.draft,hasPlayer=state.host.playerSimulated;return `<p class="eyebrow">ВЕДУЩИЙ / УЧЕБНОЕ ЛОББИ</p><h1>${esc(d.name)}</h1><section class="card"><div class="person"><div class="avatar">ГМ</div><div class="grow"><b>Ты · ведущий</b><p>Бюджет STAT: ${d.budget}</p></div><span class="pill">Локально</span></div>${hasPlayer?'<div class="person"><div class="avatar">01</div><div class="grow"><b>Учебный игрок</b><p>Смоделированный участник</p></div><span class="pill wait">Выбирает героя</span></div>':'<p class="empty">В учебном лобби пока только ведущий.</p>'}</section>${hasPlayer?'<p class="statusline">Учебный игрок добавлен. Это состояние сохраняется в этом браузере.</p>':btn('Демо: добавить учебного игрока','simulate-host-player','demo-action')}${note('Реальных игроков здесь нет. Для совместной игры потребуется отдельное подключение кампании.')}${footer('open-paths','Сменить путь')}`;}
function modalView(){if(!modal)return '';const reset=modal==='reset',fresh=modal==='new';return `<dialog id="modal" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${reset?'Сбросить это превью?':fresh?'Начать нового персонажа?':'Помощь'}</h2>${reset?'<p>Удалятся локальные черновики игрока и ведущего, учебные листы, прогресс и выбор подсказок этого превью. Другие разделы и приложение не затрагиваются.</p>':fresh?'<p>Текущий черновик будет сохранён отдельно. Новый лист начнётся с чистого имени и распределения.</p>':`<div class="stack">${btn('Анри: повторить знакомство','guide-replay','quiet')}${btn(state.guide.preference==='enabled'?'Выключить подсказки Анри':'Включить подсказки Анри','guide-toggle','quiet')}${btn('Выбрать путь игрока или ведущего','open-paths','quiet')}</div><p class="note help-note">Учётная запись, связь и участники демонстрационные. Данные сохраняются только в этом браузере. Превью не подключается к серверу и не изменяет реальные листы.</p>`}<div class="modal-actions">${btn(reset||fresh?'Отмена':'Закрыть','close-modal','quiet')}${btn(reset?'Сбросить':fresh?'Новый лист':'Сбросить превью',reset?'confirm-reset':fresh?'confirm-new':'ask-reset',reset||fresh?'primary':'danger')}</div></dialog>`;}

function render(){roleSwipe=null;root.innerHTML=`<div class="shell">${header()}<div class="workspace">${rail()}<main class="content" id="content"><div class="mobile-campaign">NC-2020 / ${state.flow==='host'?'ВЕДУЩИЙ':'НОЧНАЯ СМЕНА'} · ДЕМО</div>${guideView()}${({invitation,choose,create,review,lobby,scene,action,paths,hostSetup,hostReview,hostInvite,hostLobby}[state.screen]||invitation)()}</main></div></div>${modalView()}`;if(modal){const d=document.getElementById('modal');d.showModal();d.addEventListener('cancel',e=>{e.preventDefault();closeModal();});d.querySelector('button')?.focus();}document.title='NC Crew · '+({invitation:'Приглашение',choose:'Персонаж',create:'Создание',review:'Проверка',lobby:'Лобби',scene:'Первая сцена',action:'Первый ход',paths:'Выбор пути',hostSetup:'Твоя кампания',hostReview:'Проверка кампании',hostInvite:'Учебное приглашение',hostLobby:'Лобби ведущего'}[state.screen]||'Превью');}
function change(name,value){if(name.startsWith('host.')){act({type:'PATCH_HOST',patch:{[name.slice(5)]:name==='host.budget'?(value===''?null:Number(value)):value}},false);return;}const d=state.draft;if(name.startsWith('stat.'))patch({stats:{[name.slice(5)]:(value===''?null:Number(value))}});else if(name.startsWith('career.'))patch({careerRanks:{[name.slice(7)]:(value===''?null:Number(value))}});else if(name.startsWith('detail.'))patch({careerDetails:{[name.slice(7)]:value}},false);else if(name.startsWith('tech.')){const a=[...d.techChoices];a[Number(name.slice(5))]=value;patch({techChoices:a});}else if(name.startsWith('pickup.')){const[,i,k]=name.split('.'),a=structuredClone(d.pickup);a[Number(i)][k]=k==='rank'?(value===''?null:Number(value)):value;patch({pickup:a},k==='rank');}else if(name.startsWith('life.'))patch({lifepath:{[name.slice(5)]:value}},false);else if(['cashRoll','employmentRoll'].includes(name))patch({cash:{[name]:(value===''?null:Number(value)),stale:d.cash.stale||(d.cash.mode==='core'&&d.cash[name]!== (value===''?null:Number(value)))}},false);else if(name==='cashManual')patch({cash:{manualAmount:(value===''?null:Number(value))}},false);else patch({[name]:name==='budget'?(value===''?null:Number(value)):value},!['name','nativeLanguage','history'].includes(name));}
root.addEventListener('input',e=>{const t=e.target;if(t.name?.startsWith('host.')){change(t.name,t.value);return;}if(t.name&&t.type==='number'){const v=t.value===''?null:Number(t.value),n=t.name,d=state.draft;let p;if(n.startsWith('stat.'))p={stats:{[n.slice(5)]:v}};else if(n.startsWith('career.'))p={careerRanks:{[n.slice(7)]:v}};else if(n.startsWith('pickup.')){const[,i,k]=n.split('.'),a=structuredClone(d.pickup);a[Number(i)][k]=v;p={pickup:a};}else if(n==='budget')p={budget:v};else if(n==='cashRoll'||n==='employmentRoll')p={cash:{[n]:v,stale:d.cash.stale||(d.cash.mode==='core'&&d.cash[n]!==v)}};else if(n==='cashManual')p={cash:{manualAmount:v}};else if(n.startsWith('life.'))p={lifepath:{[n.slice(5)]:t.value}};if(p){patch(p,false);if(n==='cashRoll'||n==='employmentRoll'){const cashValue=document.getElementById('cash-value'),stale=document.getElementById('cash-stale');if(cashValue)cashValue.textContent=money(M.cashQuote(state.draft).amount);if(stale)stale.hidden=!state.draft.cash.stale;}const counter=document.querySelector('.readout strong');if(counter&&state.screen==='create'){if(state.step==='stats')counter.textContent=statsTotal()+' / '+state.draft.budget;else if(state.step==='career')counter.textContent=careerTotal()+' / 40';else if(state.step==='pickup')counter.textContent=pickupTotal()+' / '+(state.draft.stats.INT+state.draft.stats.REF);}}return;}if(t.id==='skill-search'){filter=t.value;const a=SKILLS.filter(s=>!careerIds().includes(s.id)&&(s.name+' '+s.english).toLowerCase().includes(filter.toLowerCase()));document.getElementById('skill-results').innerHTML=a.map(s=>btn(esc(s.name)+' <span class="note">'+s.stat+'</span>','add-pickup','',`data-skill="${s.id}"`)).join('');return;}if(t.name&&t.type!=='checkbox'&&t.type!=='number'&&t.tagName!=='SELECT')change(t.name,t.value);});
root.addEventListener('change',e=>{const t=e.target;if(t.name&&(t.type==='checkbox'||t.type==='number'||t.tagName==='SELECT'))change(t.name,t.type==='checkbox'?t.checked:t.value);});
root.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,d=state.draft;switch(a){case'role-mode':updateRolePicker({type:'ROLE_PICKER_MODE',mode:b.dataset.mode},'mode-'+b.dataset.mode);break;case'role-preview':updateRolePicker({type:'PREVIEW_ROLE',roleId:b.dataset.role},'preview-'+b.dataset.role);break;case'role-prev':browseRole(-1,'prev');break;case'role-next':browseRole(1,'next');break;case'role-choose':updateRolePicker({type:'PATCH_DRAFT',patch:{roleId:b.dataset.role}},'deck');break;case'guide-yes':act({type:'GUIDE_REPLY',preference:'enabled'});break;case'guide-skip':act({type:'GUIDE_REPLY',preference:'skipped'});break;case'guide-familiar':act({type:'GUIDE_REPLY',preference:'familiar'});break;case'guide-collapse':act({type:'GUIDE_COLLAPSE'});break;case'guide-replay':modalAction({type:'GUIDE_REPLAY'});break;case'guide-toggle':modalAction({type:'GUIDE_TOGGLE'});break;case'open-paths':if(modal)modalAction({type:'OPEN_PATHS'});else act({type:'OPEN_PATHS'});break;case'select-player':act({type:'SELECT_FLOW',flow:'player'});break;case'select-host':act({type:'SELECT_FLOW',flow:'host'});break;case'review-host':act({type:'REVIEW_HOST'});break;case'prepare-host-invite':act({type:'PREPARE_HOST_INVITE'});break;case'open-host-lobby':act({type:'OPEN_HOST_LOBBY'});break;case'simulate-host-player':act({type:'SIMULATE_HOST_PLAYER'});break;case'about':openModal('about');break;case'close-modal':closeModal();break;case'ask-reset':openModal('reset');break;case'confirm-reset':act({type:'REQUEST_RESET'},false);act({type:'CONFIRM_RESET'},false);modal='';restored=false;history.replaceState({onboarding:true,screen:state.screen,step:state.step},'');render();break;case'back':back();break;case'accept':act({type:'ACCEPT_INVITE'});break;case'new':if(state.drafts?.new?.name){openModal('new');}else act({type:'CHOOSE_HERO',heroId:'new'});break;case'confirm-new':modalAction({type:'NEW_DRAFT',confirmed:true});break;case'hero':act({type:'CHOOSE_HERO',heroId:b.dataset.hero});break;case'resume':act({type:'CHOOSE_HERO',heroId:'new'});break;case'step':act({type:'GO_STEP',step:b.dataset.step});break;case'next':act({type:'NEXT'});break;case'balance-stats':{const base=Math.floor(d.budget/9),extra=d.budget%9;patch({stats:Object.fromEntries(STATS.map((s,i)=>[s,base+(i<extra?1:0)]))});break;}case'role-stats':{const s=Object.fromEntries(STATS.map(k=>[k,6]));['INT','REF',d.roleId==='techie'?'TECH':'COOL'].forEach(k=>s[k]+=2);patch({stats:s});break;}case'suggest-career':{const ids=careerIds();patch({careerRanks:Object.fromEntries(ids.map(id=>[id,4]))});break;}case'suggest-pickup':{const ids=['driving','streetwise','firstaid','persuasion','perception','stealth','athletics','basictech'].map(id=>BY_ID[id]).filter(s=>s&&!careerIds().includes(s.id)&&!s.detailLabel).slice(0,4);let remaining=d.stats.INT+d.stats.REF;patch({pickup:ids.map((s,i)=>{const n=Math.min(10,Math.ceil(remaining/(ids.length-i)));remaining-=n;return{skillId:s.id,rank:n,detail:''};})});break;}case'add-pickup':patch({pickup:[...d.pickup,{skillId:b.dataset.skill,rank:1,detail:''}]});break;case'remove-pickup':patch({pickup:d.pickup.filter((_,i)=>i!==Number(b.dataset.index))});break;case'roll-cash':case'quote-cash':{const cashRoll=a==='roll-cash'?1+Math.floor(Math.random()*6):d.cash.cashRoll,employmentRoll=a==='roll-cash'?1+Math.floor(Math.random()*6):d.cash.employmentRoll;const result=M.quoteCash(d,{cashRoll,employmentRoll});patch({cash:result.cash||result});break;}case'manual-cash':patch({cash:{mode:'manual',manualConfirmed:true,stale:false}});break;case'add-gear':{const id=b.dataset.item,a=structuredClone(d.gear),item=a.find(g=>g.itemId===id);if(item)item.quantity++;else a.push({itemId:id,quantity:1,installed:false,humanityLoss:null});patch({gear:a,gearSkipped:false});break;}case'remove-gear':patch({gear:d.gear.filter((_,i)=>i!==Number(b.dataset.index))});break;case'save-and-join':act({type:'SAVE_HERO'},false);if(!state.errors?.length)act({type:'APPLY_TO_CAMPAIGN'});else render();break;case'accept-hero':act({type:'SIMULATE_ACCEPT'});break;case'ready':act({type:'TOGGLE_READY'});break;case'prepare-scene':act({type:'SIMULATE_PREPARE_SCENE'});break;case'start-turn':act({type:'SIMULATE_START_TURN'});break;case'edit-hero':act({type:'GO_STEP',step:'identity'});break;case'cell':act({type:'DECLARE_ACTION',kind:'move',x:Number(b.dataset.x),y:Number(b.dataset.y)});break;case'preview-action':act({type:'PREVIEW_ACTION'});break;case'send-action':act({type:'SEND_ACTION'});break;case'confirm-action':act({type:'SIMULATE_CONFIRM_ACTION'});break;case'again':act({type:'OPEN_CHOOSER'});break;}});
root.addEventListener('keydown',e=>{if(!e.target.closest('[data-role-deck]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const focus=e.target.dataset.pickerFocus||'deck';if(e.key==='Home'||e.key==='End')updateRolePicker({type:'PREVIEW_ROLE',roleId:ROLES[e.key==='Home'?0:ROLES.length-1].id},focus);else browseRole(e.key==='ArrowRight'?1:-1,focus);});
let roleSwipe=null;
root.addEventListener('pointerdown',e=>{roleSwipe=null;if(e.target.closest('[data-role-swipe]')&&e.isPrimary!==false&&e.button===0)roleSwipe={x:e.clientX,y:e.clientY,id:e.pointerId};});
root.addEventListener('pointerup',e=>{const start=roleSwipe;roleSwipe=null;if(!start||start.id!==e.pointerId||!e.target.closest('[data-role-swipe]'))return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>48&&Math.abs(dx)>Math.abs(dy)*1.5)browseRole(dx<0?1:-1);});
root.addEventListener('pointercancel',()=>{roleSwipe=null;});
window.addEventListener('pointerdown',()=>{roleSwipe=null;},true);
window.addEventListener('pointerup',()=>{roleSwipe=null;});
window.addEventListener('blur',()=>{roleSwipe=null;});
document.addEventListener('visibilitychange',()=>{if(document.hidden)roleSwipe=null;});
window.addEventListener('pagehide',persist);
window.addEventListener('popstate',e=>{modal=typeof e.state?.modal==='string'?e.state.modal:'';state=e.state?.onboarding?M.normalizeSession({...state,screen:e.state.screen,step:e.state.step},context):M.reduceSession(state,{type:'BACK'});depth=Math.max(0,depth-1);persist();render();});
window.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(modal){e.preventDefault();closeModal();}else if(state.guide.preference==='enabled'&&!state.guide.collapsed){e.preventDefault();act({type:'GUIDE_COLLAPSE'});}else if(state.guide.preference==='unanswered'){e.preventDefault();act({type:'GUIDE_REPLY',preference:'skipped'});}});
history.replaceState({onboarding:true,screen:state.screen,step:state.step},'');persist();render();
